/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --primary: #38bdf8;
  --primary-hover: #0284c7;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-success: #4ade80;
  --accent-danger: #f87171;
  --border-color: #334155;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.game-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 1rem;
  padding: 2rem;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.game-header .title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 0.25rem;
}

.game-header .subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  background: rgba(15, 23, 42, 0.6);
  padding: 0.75rem 1rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border-color);
}

.score-box {
  display: flex;
  flex-direction: column;
}

.score-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.target-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.badge {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  font-weight: 600;
  background: var(--border-color);
  color: var(--primary);
  padding: 0.25rem 0.6rem;
  border-radius: 9999px;
}

.rgb-value {
  font-family: monospace, monospace;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--text-main);
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  background: #0b1120;
  border: 1px dashed var(--border-color);
  user-select: all;
}

.swatches-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  min-height: 100px;
}

.swatch {
  aspect-ratio: 1 / 1;
  border-radius: 0.75rem;
  border: 3px solid rgba(255, 255, 255, 0.15);
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  outline: none;
}

.swatch:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.4);
  border-color: #ffffff;
}

.swatch:focus-visible {
  border-color: #ffffff;
  box-shadow: 0 0 0 4px var(--primary);
}

.swatch:active:not(:disabled) {
  transform: translateY(0) scale(0.98);
}

.swatch:disabled {
  cursor: not-allowed;
  opacity: 0.9;
}

.message-area {
  min-height: 2rem;
  font-size: 1.125rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
}

.message-area.correct {
  color: var(--accent-success);
}

.message-area.wrong {
  color: var(--accent-danger);
}

.actions {
  display: flex;
  justify-content: center;
}

.btn {
  font-size: 1rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  border-radius: 0.5rem;
  border: none;
  background-color: var(--primary);
  color: #0f172a;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.btn:hover {
  background-color: var(--primary-hover);
  color: #ffffff;
}

.btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

@media (max-width: 360px) {
  body {
    padding: 0.75rem;
  }

  .game-card {
    padding: 1.25rem;
    gap: 1.25rem;
  }

  .rgb-value {
    font-size: 1.25rem;
  }

  .swatches-container {
    gap: 0.5rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  let currentStreak = 0;
  let bestStreak = 0;

  try {
    bestStreak = parseInt(localStorage.getItem('pixel_color_best_streak') || '0', 10);
  } catch (e) {
    bestStreak = 0;
  }

  let targetColor = '';
  let isGameOver = false;

  const targetRgbEl = document.getElementById('targetRgb');
  const currentStreakEl = document.getElementById('currentStreak');
  const bestStreakEl = document.getElementById('bestStreak');
  const messageArea = document.getElementById('messageArea');
  const restartBtn = document.getElementById('restartBtn');
  const swatches = [
    document.getElementById('swatch-0'),
    document.getElementById('swatch-1'),
    document.getElementById('swatch-2')
  ];

  function updateScoreDisplay() {
    currentStreakEl.textContent = currentStreak;
    bestStreakEl.textContent = bestStreak;
  }

  function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function generateRgb() {
    const r = getRandomInt(0, 255);
    const g = getRandomInt(0, 255);
    const b = getRandomInt(0, 255);
    return `rgb(${r}, ${g}, ${b})`;
  }

  function generateDistinctRgb(existingColors) {
    let color;
    do {
      color = generateRgb();
    } while (existingColors.includes(color));
    return color;
  }

  function startNewRound() {
    isGameOver = false;
    messageArea.textContent = '';
    messageArea.className = 'message-area';
    restartBtn.hidden = true;

    targetColor = generateRgb();
    targetRgbEl.textContent = targetColor;

    const winningIndex = getRandomInt(0, 2);
    const options = [];

    for (let i = 0; i < 3; i++) {
      if (i === winningIndex) {
        options.push(targetColor);
      } else {
        const distractor = generateDistinctRgb([...options, targetColor]);
        options.push(distractor);
      }
    }

    swatches.forEach((swatch, idx) => {
      const color = options[idx];
      swatch.style.backgroundColor = color;
      swatch.dataset.color = color;
      swatch.disabled = false;
      swatch.style.transform = '';
      swatch.style.borderColor = '';
      swatch.setAttribute('aria-label', `Color choice ${idx + 1}`);
    });
  }

  function handleGuess(event) {
    if (isGameOver) return;

    const chosenColor = event.currentTarget.dataset.color;
    if (chosenColor === targetColor) {
      currentStreak++;
      if (currentStreak > bestStreak) {
        bestStreak = currentStreak;
        try {
          localStorage.setItem('pixel_color_best_streak', bestStreak.toString());
        } catch (e) {}
      }
      updateScoreDisplay();
      messageArea.textContent = 'Correct! Next color...';
      messageArea.className = 'message-area correct';

      swatches.forEach(swatch => swatch.disabled = true);
      setTimeout(startNewRound, 700);
    } else {
      isGameOver = true;
      currentStreak = 0;
      updateScoreDisplay();
      messageArea.textContent = 'Incorrect! Game over.';
      messageArea.className = 'message-area wrong';

      swatches.forEach(swatch => {
        swatch.disabled = true;
        if (swatch.dataset.color === targetColor) {
          swatch.style.transform = 'scale(1.08)';
          swatch.style.borderColor = '#4ade80';
        }
      });
      restartBtn.hidden = false;
      restartBtn.focus();
    }
  }

  function restartGame() {
    startNewRound();
  }

  swatches.forEach(swatch => {
    swatch.addEventListener('click', handleGuess);
  });

  restartBtn.addEventListener('click', restartGame);

  updateScoreDisplay();
  startNewRound();
});
